(function(){'use strict';
const button=document.createElement('button');button.dataset.tab='adjust';button.textContent='↗ Adjust · Growth & LTV';button.onclick=()=>tab('adjust');document.querySelector('nav').insertBefore(button,document.querySelector('[data-tab="product"]'));
const page=document.createElement('section');page.id='adjust';page.className='page';page.hidden=true;page.innerHTML=`<div class="eyebrow">ACQUISITION • MONETIZATION • ADJUST</div><h1>Install đến doanh thu.<br><span>Theo dõi giá trị tăng trưởng.</span></h1><p class="muted">Report workspace theo cấu trúc Datascape: filters → dimensions → metrics → chart → bảng.</p>
<div class="toolbar"><span id="adjSource">Chưa có report</span><button id="adjDemo">✧ Dùng Adjust demo</button><label class="ab-file">↥ Import report<input id="adjFile" type="file" accept=".csv,.tsv,.json,.xlsx,.xls" hidden></label><button id="adjExport">↓ CSV</button><button id="adjPresetExport">↓ Cấu hình report</button></div>
<article class="card"><div class="cardhead"><h2>Report filters</h2><button id="adjClear">Xóa phân khúc</button></div><div class="formgrid"><label>Khoảng thời gian<select id="adjPreset"><option value="custom">Custom</option><option value="7">Last 7 days (đến hôm qua)</option><option value="14">Last 14 days</option><option value="30">Last 30 days</option><option value="yesterday">Yesterday</option></select></label><label>Granularity<select id="adjGranularity"><option value="day">Day</option><option value="week">Week</option><option value="month">Month</option></select></label><label>Từ ngày<input id="adjFrom" type="date"></label><label>Đến ngày<input id="adjTo" type="date"></label></div><div id="adjSegments" class="formgrid ab-filters"></div><details><summary>Data settings · attribution, revenue và cohort</summary><div class="formgrid ab-filters"><label>Timezone (UTC offset)<input id="adjTimezone" value="+07:00"></label><label>Currency<input id="adjCurrency" value="USD" maxlength="3"></label><label>Attribution source<select id="adjAttribution"><option value="first">First (install source)</option><option value="dynamic">Dynamic (install + reattribution)</option></select></label><label>Attribution status<select id="adjReattributed"><option value="all">All</option><option value="false">Not reattributed</option><option value="true">Reattributed only</option></select></label><label>Attribution type<select id="adjTypes" multiple><option value="click">Click</option><option value="impression">Impression</option><option value="engaged_ad">Engaged ad</option></select></label><label>Ad spend source<select id="adjSpend"><option value="mixed">Mixed</option><option value="network">Network</option><option value="adjust">Attribution (Adjust)</option></select></label><label>IAP revenue mode<select id="adjIap"><option>GROSS_100</option><option>GROSS_85</option><option>GROSS_70</option><option>GROSS_60</option></select></label><label>Cohort maturity<select id="adjMaturity"><option value="mature">Mature</option><option value="immature">Immature (giá trị đến hiện tại)</option></select></label><label>Environment<select id="adjSandbox"><option value="false">Production</option><option value="true">Sandbox</option></select></label><label>Ad revenue sources<input id="adjAdSources" placeholder="Các API ID, ngăn cách dấu phẩy"></label><label>API period-over-period<input id="adjPeriod" placeholder="Ví dụ: previous_week"></label></div><p class="muted">Các setting này được gửi đến Adjust khi pull, không giả lập attribution hoặc quy đổi tiền trên file import. Maturity mature của Adjust có thể trả 0 cho cohort chưa đủ ngày.</p></details><details><summary>Advanced filters · bao gồm / loại trừ / điều kiện metric</summary><div id="adjAdvanced"></div><button id="adjAddFilter">+ Thêm điều kiện</button><p class="muted">Các điều kiện kết hợp bằng AND. Dùng API slug, ví dụ campaign__contains hoặc installs__gte. Include/exclude nhận nhiều giá trị ngăn cách dấu phẩy.</p></details><div class="toolbar"><button id="adjApply" class="primary">Áp dụng trên report đã tải</button><span id="adjFilterStatus" class="muted"></span></div></article>
<article class="card"><div class="cardhead"><h2>Dimensions & metrics</h2><span class="tag">REPORT BUILDER</span></div><div class="formgrid"><label>Dimensions (API slug, ngăn cách dấu phẩy)<input id="adjDimensions" value="app,app_token,os_name,country,country_code,channel,campaign,adgroup,creative"></label><label>Metrics để pull (API Metric ID)<input id="adjMetrics" value="installs,cost"></label><label>Group by trong bảng<select id="adjGroup" multiple></select></label><label>Metric trên chart<select id="adjChartMetric"></select></label><label>Breakdown đường chart<select id="adjBreakdown"></select></label><label>Top series<input id="adjTop" type="number" min="1" max="10" value="5"></label></div><details><summary>Aggregation cho metric tùy chỉnh</summary><div class="formgrid ab-filters"><label>Metric<select id="adjAggMetric"></select></label><label>Cách gộp<select id="adjAggType"><option value="raw">Không gộp (chỉ một dòng)</option><option value="sum">Sum (metric additive)</option><option value="mean">Mean không trọng số</option><option value="ratio">Ratio của tổng numerator / denominator</option></select></label><label>Numerator<select id="adjAggNum"></select></label><label>Denominator<select id="adjAggDen"></select></label></div><button id="adjSaveAgg">Áp dụng aggregation</button></details><p class="muted">Không cộng LTV, ROAS, CPI hoặc tỷ lệ. Metric chưa biết quy tắc sẽ để “—” khi phải gộp nhiều dòng; dùng source totals hoặc cấu hình ratio có mẫu số đúng.</p></article>
<div id="adjStatus" role="status"></div><div id="adjKpis" class="kpis"></div><article class="card"><div class="cardhead"><h2 id="adjChartTitle">Diễn biến metric</h2><span id="adjChartUnit" class="tag"></span></div><div id="adjChart"></div></article>
<article class="card"><div class="cardhead"><h2>LTV cohort · D1 / D3 / D7 / D30…</h2><span class="tag">OBSERVED • NOT FORECAST</span></div><div class="formgrid"><label>Horizon sau install (ngày)<input id="adjHorizon" type="number" min="1" max="180" value="7"></label><label>Ngày dữ liệu đã đầy đủ<input id="adjObservation" type="date"></label><label>Cumulative cohort revenue (đúng horizon)<select id="adjLtvRevenue"></select></label><label>Eligible cohort users (đúng horizon)<select id="adjLtvUsers"></select></label></div><div class="toolbar"><button id="adjLtvCalc">Vẽ LTV cohort</button><span id="adjLtvValue"></span></div><div id="adjLtvChart"></div><p class="muted">LTV Dn quan sát = tổng cumulative cohort revenue Dn / tổng eligible cohort users Dn. Chỉ tính install cohort đã đủ Dn; không lấy revenue theo ngày hoạt động để tính LTV. File/API cần có hai cột cohort đúng horizon. Không trộn tiền tệ.</p></article>
<article class="card"><div class="cardhead"><h2>Report table</h2><span id="adjRowCount" class="muted"></span></div><div id="adjTable" class="tablewrap"></div></article>
<article class="card"><div class="cardhead"><h2>Adjust API · Pull trực tiếp</h2><span class="tag">SERVER CONNECTION</span></div><p>Nhập Adjust API token từ Account settings → My profile. Token chỉ giữ trong tab và được gửi qua máy chủ của site để gọi Adjust; không ghi vào file, localStorage hay report export.</p><div class="formgrid"><label>Adjust API token<input id="adjToken" type="password" autocomplete="off" placeholder="Bearer token"></label><label>Tìm API metric<input id="adjMetricSearch" placeholder="revenue, ltv, roas…"></label></div><div class="toolbar"><button id="adjCatalog">Kết nối & tải danh sách filter</button><button id="adjSearchMetrics">Tìm metric trong Adjust</button><button id="adjPull" class="primary">↓ Pull report từ Adjust</button><button id="adjForget">Xóa token khỏi tab</button></div><div id="adjCatalogResults"></div><details><summary>Xem tham số request (không có token)</summary><pre id="adjParams"></pre></details><p class="muted">API metric khả dụng phụ thuộc app/package/quyền của token. Không có endpoint API tùy ý; chỉ gọi Report Service của Adjust. Report có pagination hoặc vượt 50.000 dòng bị từ chối để tránh phân tích mẫu số thiếu. <a href="https://dev.adjust.com/en/api/rs-api/reports" target="_blank" rel="noopener">Tài liệu Adjust</a></p></article>`;
document.querySelector('main').insertBefore(page,document.querySelector('footer'));
const segmentNames={app_token:'App',os_name:'OS',country_code:'Country',channel:'Channel',network:'Network',campaign:'Campaign (attribution)',campaign_network:'Campaign name (network)',adgroup:'Adgroup',creative:'Creative'};let data=[],view=[],catalog={},metadata={},isDemo=false,sourceName='',snapshot=null,specs={},rules=[],report=[];
const list=s=>String(s).split(',').map(v=>v.trim()).filter(Boolean),selected=el=>[...el.selectedOptions].map(o=>o.value),opts=(values,blank=false)=>(blank?'<option value="">Tất cả</option>':'')+values.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');
function status(s){$('adjStatus').textContent=s}
function columns(){return [...new Set(data.flatMap(Object.keys))]}
function metrics(){return columns().filter(k=>data.some(r=>AdjustReport.num(r[k])!==null)&&!AdjustReport.DIMENSIONS.includes(k)&&!['day','week','month','year','date'].includes(k))}
function segments(){const keep=Object.fromEntries([...$('adjSegments').querySelectorAll('select')].map(e=>[e.dataset.field,selected(e)]));$('adjSegments').innerHTML=Object.entries(segmentNames).map(([key,name])=>{const cat=key==='app_token'?'apps':key==='country_code'?'countries':key==='network'?'networks':key==='os_name'?'os_names':key==='channel'?'channels':null,live=cat&&Array.isArray(catalog[cat])?catalog[cat]:[],values=[...new Set([...data.map(r=>r[key]).filter(v=>v!=null&&v!==''),...live.map(r=>String(r.id))])].sort();return '<label>'+esc(name)+'<select multiple data-field="'+key+'">'+values.map(v=>'<option value="'+esc(v)+'">'+esc(live.find(r=>String(r.id)===String(v))?.name||v)+'</option>').join('')+'</select></label>'}).join('');$('adjSegments').querySelectorAll('select').forEach(e=>{[...e.options].forEach(o=>o.selected=keep[e.dataset.field]?.includes(o.value)||false);e.onchange=dirty})}
function config(){const filters=[...$('adjSegments').querySelectorAll('select')].map(e=>({field:e.dataset.field,op:'in',value:selected(e).join(',')})).filter(f=>f.value);return {from:$('adjFrom').value,to:$('adjTo').value,granularity:$('adjGranularity').value,dimensions:list($('adjDimensions').value),metrics:list($('adjMetrics').value),filters:[...filters,...rules.filter(r=>r.value.trim())],currency:$('adjCurrency').value.trim().toUpperCase(),utc_offset:$('adjTimezone').value.trim(),cohort_maturity:$('adjMaturity').value,attribution_source:$('adjAttribution').value,reattributed:$('adjReattributed').value,attribution_types:selected($('adjTypes')),ad_spend_mode:$('adjSpend').value,iap_revenue_mode:$('adjIap').value,sandbox:$('adjSandbox').value,ad_revenue_sources:$('adjAdSources').value.trim(),period_over_period:$('adjPeriod').value.trim()}}
function dirty(){view=[];report=[];$('adjKpis').innerHTML='';$('adjChart').innerHTML='';$('adjTable').innerHTML='';$('adjLtvChart').innerHTML='';$('adjLtvValue').textContent='';$('adjFilterStatus').textContent='Filters thay đổi — Apply để lọc, Pull để lấy report mới.';try{$('adjParams').textContent=JSON.stringify(AdjustReport.parameters(config()),null,2)}catch(e){$('adjParams').textContent=e.message}}
function renderRules(){$('adjAdvanced').innerHTML=rules.map((r,i)=>'<div class="maprow"><input data-rule-field="'+i+'" value="'+esc(r.field)+'" placeholder="API slug"><select data-rule-op="'+i+'">'+AdjustReport.OPERATORS.map(op=>'<option '+(op===r.op?'selected':'')+'>'+op+'</option>').join('')+'</select><div class="toolbar"><input data-rule-value="'+i+'" value="'+esc(r.value)+'" placeholder="Giá trị"><button data-rule-remove="'+i+'">×</button></div></div>').join('');for(const name of ['field','op','value'])$('adjAdvanced').querySelectorAll('[data-rule-'+name+']').forEach(e=>e.onchange=()=>{rules[+e.getAttribute('data-rule-'+name)][name]=e.value;dirty()});$('adjAdvanced').querySelectorAll('[data-rule-remove]').forEach(e=>e.onclick=()=>{rules.splice(+e.dataset.ruleRemove,1);renderRules();dirty()})}
$('adjAddFilter').onclick=()=>{rules.push({field:'campaign',op:'contains',value:''});renderRules()};
function dateOf(r){const v=String(r.day??r.week??r.month??r.date??'').slice(0,10);return /^\d{4}-\d{2}$/.test(v)?v+'-01':v}
function adopt(input,name,demoFlag=false,params=null){data=AdjustReport.unpack(input);view=[];report=[];metadata=Array.isArray(input)?{}:input;sourceName=name;isDemo=demoFlag;snapshot=params;specs={};$('adjSource').textContent=(isDemo?'● DEMO · ':'● REPORT · ')+name;const dates=data.map(dateOf).filter(v=>AdjustReport.validDate(v)).sort();if(dates.length){$('adjFrom').value=dates[0];$('adjTo').value=dates.at(-1)}if(!params)$('adjObservation').value=new Date().toISOString().slice(0,10);segments();const ms=metrics();$('adjChartMetric').innerHTML=opts([...ms,...(ms.includes('cost')&&ms.includes('installs')?['cpi']:[])]);$('adjAggMetric').innerHTML=opts(ms);for(const id of ['adjAggNum','adjAggDen','adjLtvRevenue','adjLtvUsers'])$(id).innerHTML='<option value="">Chọn cột</option>'+opts(ms);$('adjGroup').innerHTML=opts(AdjustReport.DIMENSIONS.filter(d=>columns().includes(d)));const defaults=['channel'];[...$('adjGroup').options].forEach(o=>o.selected=defaults.includes(o.value));$('adjBreakdown').innerHTML=opts(AdjustReport.DIMENSIONS.filter(d=>columns().includes(d)),true);$('adjBreakdown').value=columns().includes('channel')?'channel':'';autoLtvColumns();syncAgg();apply()}
function currency(){const set=[...new Set(view.map(r=>r.currency_code).filter(Boolean))];return set.length===1?set[0]:set.length>1?'MIXED':snapshot?.currency||'đơn vị theo file'}
function apply(){try{if(!data.length){view=[];$('adjChart').innerHTML='<p class="muted">Chưa có dữ liệu. Dùng demo hoặc pull/import report.</p>';return}const c=config();AdjustReport.parameters(c);for(const f of c.filters)if(!columns().includes(f.field))throw Error('Report chưa có cột '+f.field+'. Thêm dimension và Pull lại để lọc.');if(snapshot){if(c.from<snapshot.from||c.to>snapshot.to||c.granularity!==snapshot.granularity)throw Error('Khoảng ngày/granularity vượt report đã tải: Pull lại từ Adjust.');for(const key of ['currency','utc_offset','cohort_maturity','attribution_source','reattributed','ad_spend_mode','iap_revenue_mode','sandbox','ad_revenue_sources','attribution_types'])if(JSON.stringify(c[key])!==JSON.stringify(snapshot[key]))throw Error('Setting '+key+' thay đổi: cần Pull lại từ Adjust.')}view=AdjustReport.filter(data.map(r=>({...r,day:dateOf(r)})),c);if(new Set(view.map(r=>r.currency_code).filter(Boolean)).size>1)throw Error('Report có nhiều tiền tệ. Thêm filter currency_code hoặc pull với currency thống nhất.');const ms=metrics(),groups=selected($('adjGroup'));report=AdjustReport.group(view,groups,ms,specs);$('adjTable').innerHTML=table(report,200);$('adjRowCount').textContent=view.length+' dòng nguồn → '+report.length+' nhóm';const kpis=[['Installs','installs'],['Revenue','revenue'],['Ad spend','cost'],['CPI','cpi']];$('adjKpis').innerHTML=kpis.map(([name,k])=>{const value=AdjustReport.aggregate(view,k,specs[k]);return '<div class="kpi"><small>'+name+'</small><strong>'+fmt(value)+'</strong><div class="change">'+(k==='installs'?'Tổng install':esc(currency()))+'</div></div>'}).join('');$('adjFilterStatus').textContent='Đã áp dụng · '+view.length+' dòng';status((isDemo?'DEMO · ':'')+(metadata.warnings?.length?'Adjust warnings: '+JSON.stringify(metadata.warnings):'Report đang xem: '+sourceName)+(!snapshot?' · Setting API không quy đổi trên file.':''));draw();drawLtv()}catch(e){dirty();status(e.message)}}
function draw(){if(!view.length){$('adjChart').innerHTML='<p class="muted">Không có dữ liệu trong phạm vi lọc.</p>';return}const metric=$('adjChartMetric').value,dim=$('adjBreakdown').value,top=Math.max(1,Math.min(10,Number($('adjTop').value)||5));const groups=dim?[...new Set(view.map(r=>String(r[dim]??'—')))].sort((a,b)=>Math.abs(AdjustReport.aggregate(view.filter(r=>String(r[dim]??'—')===b),metric,specs[metric])||0)-Math.abs(AdjustReport.aggregate(view.filter(r=>String(r[dim]??'—')===a),metric,specs[metric])||0)).slice(0,top):['Toàn bộ'];const dates=[...new Set(view.map(dateOf))].sort();const series=groups.map(name=>({name,points:dates.map(date=>{const subset=view.filter(r=>dateOf(r)===date&&(!dim||String(r[dim]??'—')===name));return {x:date,y:AdjustReport.aggregate(subset,metric,specs[metric]),n:subset.length}})}));$('adjChartTitle').textContent='Diễn biến '+metric;$('adjChartUnit').textContent=currency();$('adjChart').innerHTML=MetricCharts.chart(series,{label:metric+' theo ngày'})}
function autoLtvColumns(){const n=Number($('adjHorizon').value),ms=metrics();$('adjLtvRevenue').value=ms.includes('cohort_revenue_d'+n)?'cohort_revenue_d'+n:'';$('adjLtvUsers').value=ms.includes('cohort_users_d'+n)?'cohort_users_d'+n:''}
function drawLtv(){try{if(!view.length)return;const chosenHorizon=Number($('adjHorizon').value);if(['adjLtvRevenue','adjLtvUsers'].some(id=>{const m=$(id).value.match(/^cohort_(?:revenue|users)_d(\d+)$/);return m&&Number(m[1])!==chosenHorizon}))autoLtvColumns();const c={horizon:Number($('adjHorizon').value),observation:$('adjObservation').value,numerator:$('adjLtvRevenue').value,denominator:$('adjLtvUsers').value};if(!c.numerator||!c.denominator){$('adjLtvValue').textContent='Chọn cumulative cohort revenue và eligible users đúng horizon.';$('adjLtvChart').innerHTML='';return}const v=AdjustReport.ltv(view,c);$('adjLtvValue').textContent='LTV D'+c.horizon+' = '+fmt(v.value)+' '+currency()+' · '+fmt(v.users)+' eligible users · bỏ qua '+v.excludedRows+' dòng';const dim=$('adjBreakdown').value,names=dim?[...new Set(view.map(r=>String(r[dim]??'—')))].slice(0,10):['Toàn bộ'],dates=[...new Set(view.map(dateOf))].sort();$('adjLtvChart').innerHTML=MetricCharts.chart(names.map(name=>({name,points:dates.map(date=>{const subset=view.filter(r=>dateOf(r)===date&&(!dim||String(r[dim]??'—')===name)),a=AdjustReport.ltv(subset,c);return {x:date,y:a.value,n:a.users}})})),{label:'LTV D'+c.horizon+' theo ngày install cohort'})}catch(e){$('adjLtvValue').textContent=e.message;$('adjLtvChart').innerHTML=''}}
function syncAgg(){const s=specs[$('adjAggMetric').value]||AdjustReport.metricSpec($('adjAggMetric').value);$('adjAggType').value=s.type;$('adjAggNum').value=s.numerator||'';$('adjAggDen').value=s.denominator||''}
$('adjSaveAgg').onclick=()=>{const type=$('adjAggType').value,numerator=$('adjAggNum').value,denominator=$('adjAggDen').value;if(type==='ratio'&&(!numerator||!denominator)){status('Chọn numerator và denominator.');return}specs[$('adjAggMetric').value]={type,numerator,denominator};apply()};$('adjAggMetric').onchange=syncAgg;
function presets(){const today=new Date(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'T00:00:00Z'),end=new Date(+today-864e5),p=$('adjPreset').value;if(p==='custom')return;const n=p==='yesterday'?1:Number(p);$('adjTo').value=end.toISOString().slice(0,10);$('adjFrom').value=new Date(+end-(n-1)*864e5).toISOString().slice(0,10);dirty()}
$('adjPreset').onchange=presets;$('adjApply').onclick=apply;$('adjClear').onclick=()=>{rules=[];renderRules();$('adjSegments').querySelectorAll('select').forEach(e=>[...e.options].forEach(o=>o.selected=false));dirty()};['adjFrom','adjTo','adjGranularity','adjDimensions','adjMetrics','adjCurrency','adjTimezone','adjMaturity','adjAttribution','adjReattributed','adjTypes','adjSpend','adjIap','adjSandbox','adjAdSources','adjPeriod'].forEach(id=>$(id).addEventListener('change',dirty));['adjGroup'].forEach(id=>$(id).onchange=apply);['adjChartMetric','adjBreakdown','adjTop'].forEach(id=>$(id).onchange=()=>{draw();drawLtv()});$('adjHorizon').onchange=()=>{autoLtvColumns();drawLtv()};$('adjObservation').onchange=drawLtv;$('adjLtvCalc').onclick=drawLtv;
async function api(kind,params){const r=await fetch('/api/adjust/'+kind,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('adjToken').value.trim(),params})});let j;try{j=await r.json()}catch{throw Error('API server chưa sẵn sàng. Mở bản đã publish để kết nối.')}if(!r.ok)throw Error(j.error||'HTTP '+r.status);return j}
function pendingTask(fn){return async()=>{const buttons=['adjPull','adjCatalog','adjSearchMetrics'];buttons.forEach(id=>$(id).disabled=true);try{await fn()}catch(e){status(e.message)}finally{buttons.forEach(id=>$(id).disabled=false)}}}
$('adjCatalog').onclick=pendingTask(async()=>{status('Đang tải danh sách filter từ Adjust…');const result=await api('catalog',{required_filters:'apps,countries,networks,os_names,dimensions,channels'});catalog=result.data||result;segments();status('Đã kết nối và tải catalog. Chọn filter rồi Pull report.')});
$('adjSearchMetrics').onclick=pendingTask(async()=>{const result=await api('catalog',{required_filters:'metrics',metrics__contains:$('adjMetricSearch').value.trim()});const values=result.data?.metrics||[];$('adjCatalogResults').innerHTML=values.slice(0,100).map((m,i)=>'<div class="ab-metric"><div><b>'+esc(m.name||m.id)+'</b><p class="muted">'+esc(m.id)+' · '+esc(m.description||'')+'</p></div><button data-add-api-metric="'+i+'">+ Metric</button></div>').join('')||'<p class="muted">Không tìm thấy metric. Kiểm tra API Metric ID trong glossary Adjust.</p>';$('adjCatalogResults').querySelectorAll('button').forEach(b=>b.onclick=()=>{const ms=list($('adjMetrics').value);if(!ms.includes(values[+b.dataset.addApiMetric].id))ms.push(values[+b.dataset.addApiMetric].id);$('adjMetrics').value=ms.join(',');dirty()});status('Đã tìm metric catalog. API ID có thể phụ thuộc package.')});
$('adjPull').onclick=pendingTask(async()=>{const c=config(),params=AdjustReport.parameters(c);$('adjParams').textContent=JSON.stringify(params,null,2);status('Đang pull report từ Adjust…');const result=await api('report',params);adopt(result.data||result,'Adjust API · '+(result.receivedAt||new Date().toISOString()),false,c);status('Đã pull '+data.length+' dòng'+(metadata.warnings?.length?' · warnings: '+JSON.stringify(metadata.warnings):''))});$('adjForget').onclick=()=>{$('adjToken').value='';status('Đã xóa token khỏi tab.')};
$('adjFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('File vượt 20 MB.');let d;if(/\.xlsx?$/i.test(f.name)){const w=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true});d=XLSX.utils.sheet_to_json(w.Sheets[w.SheetNames[0]],{raw:true,defval:''})}else d=/\.json$/i.test(f.name)?JSON.parse(await f.text()):csvParse(await f.text());d=d.map(row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k,v instanceof Date?v.toISOString().slice(0,10):v])));rules=[];renderRules();catalog={};$('adjSegments').innerHTML='';adopt(d,f.name)}catch(err){status(err.message)}e.target.value=''};
$('adjPresetExport').onclick=()=>download('adjust-report-config.json',JSON.stringify({version:1,config:config(),aggregations:specs},null,2),'application/json');$('adjExport').onclick=()=>{if(!report.length){status('Apply report trước khi xuất.');return}const keys=Object.keys(report[0]),cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('adjust-report.csv','\uFEFF'+[keys.map(cell).join(','),...report.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv')};
$('adjDemo').onclick=()=>{let d=[];for(let n=0;n<45;n++)for(let j=0;j<3;j++){const day=new Date(Date.UTC(2026,7,1+n)).toISOString().slice(0,10),installs=Math.round((420+j*150)*(1+n*.018)),cost=j?Math.round(installs*(.8+j*.3)):0,revenue=Math.round(installs*(.45+n*.012+j*.06));const r={day,app:'Puzzle Garden',app_token:'demo_app',os_name:j%2?'ios':'android',country:j%2?'United States':'Vietnam',country_code:j%2?'US':'VN',channel:['Organic','Google Ads','AppLovin'][j],network:['Organic','Google Ads','AppLovin'][j],campaign:'Campaign '+j,campaign_network:'Campaign '+j,adgroup:'Adgroup '+(n%2),creative:'Video '+j,currency_code:'USD',installs,cost,revenue,clicks:installs*5,impressions:installs*50};for(const h of [1,3,7,14,30,60,90]){r['cohort_users_d'+h]=installs;r['cohort_revenue_d'+h]=Math.round(installs*(.06*h+.09*j)*(1+n*.005))}d.push(r)}rules=[];renderRules();catalog={};$('adjSegments').innerHTML='';$('adjObservation').value='2026-10-13';adopt(d,'Adjust-style report · 45 days',true);$('adjObservation').value='2026-10-13';drawLtv()};
$('adjPreset').value='14';presets();$('adjObservation').value=new Date().toISOString().slice(0,10);segments();renderRules();$('adjGroup').innerHTML=opts(AdjustReport.DIMENSIONS);$('adjBreakdown').innerHTML=opts(AdjustReport.DIMENSIONS,true);$('adjParams').textContent=JSON.stringify(AdjustReport.parameters(config()),null,2);
})();
